     TABLE(['المهارة', 'قبل أسبوعين', 'الآن', 'الخطوة التالية'], [['تتبّع الحرف «ب»', 'بمساعدة', 'وحده', 'حرف «ت»'], ['الجمع حتى ١٠', 'لا يعرفها', 'بمساعدة', 'تمارين بأشياء ملموسة']]),
