     TABLE(['بدل أن تقول', 'قل'], [['أنت ذكي جدًا!', 'تعبت في الحل وكنت صبورًا.'], ['كم أنت سريع!', 'راجعت إجابتك قبل أن تسلّمها، أحسنت.'], ['لماذا أخطأت؟', 'لنرَ الخطوة التي نحتاج أن نعدلها.'], ['أخوك أفضل منك', 'لقد تحسنت عن الأسبوع الماضي.']]),
